@mark.parametrize(("params", "expect"), RULES_CASES)
async def test_endpoint_rules(params: dict[str, Any], expect: dict[str, Any]) -> None:
    check_rules_case(
        await _endpoint_resolver(), params, expect, extensions=_RULES_EXTENSIONS
    )


